// Full-screen chapter changes. New requests wait for the current wipe to settle.
let wipeChain=Promise.resolve();
function wipe(change){const task=async()=>{if(!motion){await change();return;}const layer=$('#transition'),bars=[...layer.querySelectorAll('i')],label=layer.querySelector(':scope>span');layer.style.visibility='visible';const opts={duration:430,easing:'cubic-bezier(.76,0,.24,1)',fill:'forwards'};try{await Promise.all(bars.map((bar,i)=>bar.animate([{transform:`translateX(${i%2?102:-102}%)`},{transform:'translateX(0)'}],{...opts,delay:i*25}).finished));const textAnimation=label.animate([{opacity:0,transform:'translateY(30px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,fill:'forwards'});await textAnimation.finished;await change();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));label.animate([{opacity:1},{opacity:0}],{duration:150,fill:'forwards'});await Promise.all(bars.map((bar,i)=>bar.animate([{transform:'translateX(0)'},{transform:`translateX(${i%2?-102:102}%)`}],{...opts,delay:i*18}).finished));}finally{layer.style.visibility='hidden';layer.getAnimations({subtree:true}).forEach(a=>a.cancel());}};wipeChain=wipeChain.then(task,task);return wipeChain;}
const menu=$('#navigation'),menuToggle=$('#menu-toggle');
