menuToggle.addEventListener('click',()=>{if(menu.open){closeMenu();return;}menu.showModal();body.classList.add('locked');menuToggle.setAttribute('aria-expanded','true');menuToggle.setAttribute('aria-label','Close navigation');if(motion){menu.animate([{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0 0)'}],{duration:600,easing:'cubic-bezier(.76,0,.24,1)'});$$('.menu-content nav a').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(55px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,delay:150+i*50,fill:'both',easing:'cubic-bezier(.22,1,.36,1)'}));}$('.menu-content nav a').focus({preventScroll:true});});
