$$('[data-menu]').forEach(link=>{const preview=()=>{$('.menu-preview-number').textContent=String(Number(link.dataset.menu)+1).padStart(2,'0');$('.menu-preview').style.setProperty('--menu-turn',`${(Number(link.dataset.menu)-2)*12}deg`);};link.addEventListener('pointerenter',preview);link.addEventListener('focus',preview);link.addEventListener('click',e=>{e.preventDefault();wipe(()=>{closeMenu();const target=$(link.getAttribute('href'));target.scrollIntoView({behavior:'instant'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});measure();schedule();});});});
const detailDialog=$('#project-dialog'),detail=$('#project-detail');let openedFromPage=false,opener=null,renderedRoute='',routeBusy=false,routeAgain=false;
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderProject(key){const p=projects[key],keys=Object.keys(projects),next=keys[(keys.indexOf(key)+1)%keys.length];detailDialog.className=`project-dialog ${key}`;detail.innerHTML=`<div class="detail-top"><p class="micro">${escapeHTML(p.index)} / 04 — ${escapeHTML(p.status)}</p><h2 id="detail-title">${escapeHTML(p.name)}</h2><p class="detail-subtitle">${escapeHTML(p.subtitle)}</p></div><div class="detail-hero media-canvas" data-media="${key}" aria-label="${escapeHTML(p.name)} main media canvas"><span class="registration" aria-hidden="true"></span></div><div class="detail-body"><p class="detail-summary">${escapeHTML(p.summary)}</p><div><ul class="detail-points">${p.details.map(text=>`<li>${escapeHTML(text)}</li>`).join('')}</ul><div class="detail-links"><a class="pill dark" href="${p.source}" target="_blank" rel="noreferrer">SOURCE CODE ↗</a>${p.live?`<a class="pill light" href="${p.live}" target="_blank" rel="noreferrer">${p.liveLabel?'BROWSER CLIENT':'VISIT WEBSITE'} ↗</a>`:''}</div></div></div><div class="detail-secondary media-canvas" data-media="${key}-detail" aria-label="${escapeHTML(p.name)} detail media canvas"><span class="registration" aria-hidden="true"></span></div><a class="detail-next" href="#project/${next}"><small>CONTINUE EXPLORING / ${projects[next].index}</small><span>${escapeHTML(projects[next].name)}</span><span>↗</span></a>`;populateMedia(detail);if(!detailDialog.open)detailDialog.showModal();body.classList.add('locked');detailDialog.scrollTop=0;$('#detail-close').focus({preventScroll:true});}
async function syncRoute(immediate=false){if(routeBusy){routeAgain=true;return;}routeBusy=true;do{routeAgain=false;const key=location.hash.startsWith('#project/')?location.hash.slice(9):'',valid=Object.hasOwn(projects,key),next=valid?key:'';if(next!==renderedRoute){const change=()=>{if(valid)renderProject(key);else if(detailDialog.open){detailDialog.close();body.classList.remove('locked');if(opener?.isConnected)opener.focus({preventScroll:true});}renderedRoute=next;};if(immediate)change();else await wipe(change);}}while(routeAgain);routeBusy=false;}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#project/"]');if(!link)return;e.preventDefault();const key=link.hash.slice(9);if(!Object.hasOwn(projects,key))return;if(!detailDialog.open){opener=link;openedFromPage=true;history.pushState({portfolio:true},'',link.hash);}else history.replaceState({portfolio:openedFromPage},'',link.hash);syncRoute();});
