// The spatial room uses real CSS perspective: empty planes are the content slots.
const notes={system:['Built around the way I think.','Arch Linux and Openbox. A lightweight environment, shaped through dotfiles, with just enough structure to stay out of the way.'],tools:['Small tools. Connected thoughts.','Alacritty, Neovim, tmux, Bash, and Git. A focused collection of tools that can be understood, changed, and put back together.'],mindset:['Take it apart. Make it yours.','A place for curiosity: explicit choices, reversible changes, and the freedom to keep learning how the pieces work.']};let roomX=-13,roomY=-7,drag=null;
function roomTransform(){const n=Number(room.dataset.note||0);$('.room-perspective').style.transform=`rotateX(${roomY}deg) rotateY(${roomX+n*7}deg)`;}
$$('[data-inspect]').forEach((b,i)=>b.addEventListener('click',()=>{const key=b.dataset.inspect;$$('[data-inspect]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));$('#inspector-title').textContent=notes[key][0];$('#inspector-copy').textContent=notes[key][1];room.dataset.note=String(i);roomTransform();if(motion)$('.workspace-copy').animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'ease-out'});}));
room.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;drag={x:e.clientX,y:e.clientY,rx:roomX,ry:roomY};room.setPointerCapture(e.pointerId);$('.room-perspective').style.transition='none';});room.addEventListener('pointermove',e=>{if(!drag)return;roomX=clamp(drag.rx+(e.clientX-drag.x)*.12,-40,40);roomY=clamp(drag.ry-(e.clientY-drag.y)*.08,-25,25);roomTransform();});function endRoom(){drag=null;$('.room-perspective').style.transition='';}room.addEventListener('pointerup',endRoom);room.addEventListener('pointercancel',endRoom);room.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home'){roomX=-13;roomY=-7;}if(e.key==='ArrowLeft')roomX-=5;if(e.key==='ArrowRight')roomX+=5;if(e.key==='ArrowUp')roomY-=5;if(e.key==='ArrowDown')roomY+=5;roomX=clamp(roomX,-40,40);roomY=clamp(roomY,-25,25);roomTransform();});
